export function stillOut(loans: Loan[]): Record<GearKind, number> {
  const result = {} as Record<GearKind, number>;
  for (const kind of GEAR_KINDS) {
    result[kind] = 0;
  }
  for (const loan of loans) {
    if (loan.settled) continue;
    for (const line of loan.lines) {
      result[line.kind] += line.issued - line.back;
    }
  }
  return result;
}
